    "принц":    np.array([0.7, 0.8, 0.2, 0.6]),
    "яблоко":   np.array([0.1, 0.1, 0.1, 0.9]),
}

def cos(a, b):
    return a @ b / (np.linalg.norm(a) * np.linalg.norm(b))

target = emb["король"] - emb["мужчина"] + emb["женщина"]
candidates = [w for w in emb if w not in ("король", "мужчина", "женщина")]
result = max(candidates, key=lambda w: cos(emb[w], target))

